import React, { useMemo } from 'react';
import { useCalendarGridInteraction } from './useCalendarGridInteraction';
// Ensure cn utility exists or fallback to manual string concat if utility is missing in project
// Assuming this project uses tailwind-merge/clsx pattern based on prev file
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs) {
    return twMerge(clsx(inputs));
}

export default function CalendarGrid({
    courts = [],
    openHour = 7,
    closeHour = 22,
    bookings = {},
    slots = [],
    currentDate = new Date(),
    onTimeSelect,
    onBookingClick,
    isEditMode = false,
    modifiedSlots = {},
    onSlotMove
}) {
    // 1. Filter Slots for Display (Match Date)
    const currentYMD = currentDate.toLocaleDateString("en-CA");

    // Merge modified slots into display
    // If a slot is in modifiedSlots, use that version instead of the one in 'slots' array
    const effectiveSlots = useMemo(() => {
        const baseSlots = slots.filter(slot => {
            return slot.date === currentYMD && slot.status === "ACTIVE";
        });

        if (!isEditMode) return baseSlots;

        return baseSlots.map(s => {
            if (modifiedSlots[s.slotId]) {
                return { ...s, ...modifiedSlots[s.slotId] };
            }
            return s;
        });
    }, [slots, currentYMD, isEditMode, modifiedSlots]);

    // 2. Generate Time Chunks (Hourly)
    const timeSlots = useMemo(() => {
        const chunks = [];
        for (let h = openHour; h < closeHour; h++) {
            chunks.push({ hour: h, minute: 0, label: `${h}:00` });
        }
        return chunks;
    }, [openHour, closeHour]);

    const {
        handleMouseDown,
        handleMouseEnter,
        handleMouseUp,
        handleTouchStart,
        handleTouchMove,
        handleTouchEnd,
        selectionBox
    } = useCalendarGridInteraction({
        courts,
        onSelectionComplete: onTimeSelect
    });

    const isSelected = (courtId, timeVal) => {
        if (!selectionBox) return false;
        const s = selectionBox.start;
        const e = selectionBox.end;

        // Court Range
        // Use String() to handle mismatch between numeric IDs (props) and string IDs (DOM attributes)
        const cIdx = courts.findIndex(c => String(c.id) === String(courtId));
        const sIdx = courts.findIndex(c => String(c.id) === String(s.courtId));
        const eIdx = courts.findIndex(c => String(c.id) === String(e.courtId));

        const minC = Math.min(sIdx, eIdx);
        const maxC = Math.max(sIdx, eIdx);

        // Time Range
        const minT = Math.min(s.time, e.time);
        const maxT = Math.max(s.time, e.time);

        return (cIdx >= minC && cIdx <= maxC) && (timeVal >= minT && timeVal <= maxT);
    };

    // --- Drag & Drop Handlers ---
    const handleDragStart = (e, slotId) => {
        if (!isEditMode) return;
        e.dataTransfer.setData("text/plain", slotId);
        e.dataTransfer.effectAllowed = "move";
        // e.target.style.opacity = '0.5'; // Visual feedback
    };

    const handleDragOver = (e) => {
        if (!isEditMode) return;
        e.preventDefault(); // Allow drop
        e.dataTransfer.dropEffect = "move";
    };

    const handleDrop = (e, courtId, timeInMinutes) => {
        if (!isEditMode) return;
        e.preventDefault();
        const slotId = e.dataTransfer.getData("text/plain");
        if (onSlotMove) {
            onSlotMove(slotId, timeInMinutes, courtId);
        }
    };

    return (
        <div
            className="select-none overflow-auto pb-20 relative bg-white h-full"
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
        >
            <div className="min-w-[1000px]">
                {/* Header Row */}
                <div className="flex border-b border-slate-100 sticky top-0 bg-white z-20 shadow-sm ml-24">
                    {timeSlots.map((slot, i) => (
                        <div key={i} className="flex-1 min-w-[60px] h-10 border-r border-slate-50 relative flex items-end pb-1 justify-center">
                            {slot.label && (
                                <span className="text-xs font-medium text-slate-400 font-mono transform -translate-x-1/2 absolute left-0 bottom-1 bg-white px-1">
                                    {slot.label}
                                </span>
                            )}
                        </div>
                    ))}
                </div>

                {/* Grid Rows */}
                <div className="relative">
                    {courts.map(court => (
                        <div key={court.id} className="flex h-24 border-b border-slate-100 group">
                            {/* Court Label */}
                            <div className="w-24 flex-shrink-0 sticky left-0 bg-white z-10 border-r border-slate-100 flex items-center justify-center font-bold text-slate-700 shadow-[4px_0_24px_-12px_rgba(0,0,0,0.1)]">
                                {court.name}
                            </div>

                            {/* Cells */}
                            {timeSlots.map((timeSlot, i) => {
                                const timeInMinutes = timeSlot.hour * 60 + timeSlot.minute;

                                // Find if this cell is occupied by a ACTIVE slot in 'effectiveSlots'
                                const activeSlot = effectiveSlots.find(s => {
                                    if (String(s.courtId) !== String(court.id)) return false;

                                    // Soft Delete Logic: Ignore CANCELLED bookings
                                    const b = bookings[s.bookingId];
                                    if (b && b.status === 'CANCELLED') return false;

                                    // Use integer minutes directly
                                    return timeInMinutes >= s.startTime && timeInMinutes < s.endTime;
                                });

                                const selected = isSelected(court.id, timeInMinutes);
                                const isStart = activeSlot && activeSlot.startTime === timeInMinutes;

                                let parentBooking = null;
                                let cellStyle = "";
                                let label = "";
                                let isModified = activeSlot && modifiedSlots[activeSlot.slotId];

                                if (activeSlot) {
                                    parentBooking = bookings[activeSlot.bookingId];
                                    if (parentBooking) {
                                        if (parentBooking.type === "OPEN_PLAY_BLOCK") {
                                            cellStyle = "bg-blue-50 text-blue-600 border-blue-200 border-l-4 border-l-blue-400";
                                        } else {
                                            // RENTAL
                                            label = parentBooking.renter?.name || "Occupied";

                                            // Dynamic Status Check
                                            // Use paymentSummary.totalAmount as authoritative total (respects discounts).
                                            // Fall back to raw slot sum only if paymentSummary is missing.
                                            const pSum = parentBooking.paymentSummary || {};
                                            const allBookingSlots = slots.filter(s => s.bookingId === parentBooking.id);
                                            const rawSlotTotal = allBookingSlots.reduce((sum, s) => sum + (s.price || 0), 0);
                                            const effectiveTotal = (pSum.totalAmount !== undefined && pSum.totalAmount !== null)
                                                ? pSum.totalAmount
                                                : rawSlotTotal;
                                            const isPaid = (pSum.amountPaid || 0) >= effectiveTotal && effectiveTotal > 0;
                                            const isPartial = !isPaid && (pSum.amountPaid || 0) > 0;

                                            if (isPaid) {
                                                cellStyle = "bg-emerald-100 text-emerald-800 border-emerald-200";
                                            } else if (isPartial) {
                                                // Yellow
                                                cellStyle = "bg-yellow-100 text-yellow-800 border-yellow-200 border-l-4 border-l-yellow-400";
                                            } else {
                                                // UNPAID -> Firey Red
                                                cellStyle = "bg-red-50 text-red-900 border-red-200 border-l-4 border-l-red-500";
                                            }
                                        }

                                        if (isModified) {
                                            cellStyle = "bg-blue-100 text-blue-900 border-blue-300 ring-2 ring-blue-500/20 z-10";
                                        }
                                    }
                                }

                                return (
                                    <div
                                        key={i}
                                        className={cn(
                                            "flex-1 min-w-[60px] border-r border-slate-50 relative transition-colors duration-75",
                                            !activeSlot && selected && "bg-emerald-500/20",
                                            !activeSlot && !selected && !isEditMode && "hover:bg-slate-50",
                                            timeSlot.minute === 0 && "border-r-slate-100",
                                            isEditMode && !activeSlot && "hover:bg-blue-50/50" // Hint drop zone
                                        )}
                                        // Mobile Touch Events (Long Press Selection)
                                        onTouchStart={() => !isEditMode && !activeSlot && handleTouchStart(court.id, timeInMinutes)}
                                        onTouchMove={handleTouchMove}
                                        onTouchEnd={handleTouchEnd}
                                        data-court-id={court.id}
                                        data-time={timeInMinutes}

                                        // Disable standard mouse events if Edit Mode
                                        onMouseDown={() => !isEditMode && !activeSlot && handleMouseDown(court.id, timeInMinutes)}
                                        onMouseEnter={() => !isEditMode && !activeSlot && handleMouseEnter(court.id, timeInMinutes)}

                                        // Drag Over / Drop
                                        onDragOver={handleDragOver}
                                        onDrop={(e) => handleDrop(e, court.id, timeInMinutes)}
                                    >
                                        {activeSlot && parentBooking && (
                                            <div
                                                draggable={isEditMode}
                                                onDragStart={(e) => handleDragStart(e, activeSlot.slotId)}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (!isEditMode) {
                                                        onBookingClick && onBookingClick(parentBooking.id);
                                                    }
                                                }}
                                                className={cn(
                                                    "absolute inset-0 m-0.5 rounded flex items-center justify-center text-[10px] font-bold truncate px-1 shadow-sm transition-all border",
                                                    cellStyle,
                                                    // Remove cursor-default enforcement so Edit Mode drag works
                                                    !isEditMode && "cursor-pointer hover:brightness-95",
                                                    isEditMode && "cursor-move hover:scale-[1.02] hover:shadow-md hover:ring-2 ring-emerald-400/50 z-20"
                                                )}
                                                style={{ zIndex: isModified ? 30 : 1 }}
                                            >
                                                {isStart && (
                                                    <>
                                                        {parentBooking.type === "OPEN_PLAY_BLOCK" ? (parentBooking.title || "Open Play") : (
                                                            <>
                                                                {label}
                                                                {parentBooking.renter?.discount > 0 && (
                                                                    <span className="ml-0.5 opacity-70">%</span>
                                                                )}
                                                            </>
                                                        )}
                                                        {isModified && <span className="ml-1 text-[8px] bg-blue-600 text-white rounded px-1">MOD</span>}
                                                    </>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    ))}
                </div>
            </div>

            {/* Inline Style for Striped Background (Unpaid/Warning) */}
            <style>{`
                .striped-bg {
                    background-image: repeating-linear-gradient(
                        45deg,
                        transparent,
                        transparent 5px,
                        rgba(255, 255, 255, 0.4) 5px,
                        rgba(255, 255, 255, 0.4) 10px
                    );
                }
            `}</style>
        </div>
    );
}
